-		switch {
-		case c.Class == "func":
-			hint = c.Type
-		case c.Type == "":
-			hint = c.Class
-		default:
-			hint = c.Class + " " + c.Type
-		}
-		fmt.Fprintf(w, "%s,,%s\n", c.Name, hint)
-	}
