-		l = l[:n-1]
-	}
-	n := len(l)
-	if n >= 2 && KnownOS[l[n-2]] && KnownArch[l[n-1]] {
-		return l[n-2], l[n-1], true
-	}
-	if n >= 1 && KnownOS[l[n-1]] {
-		return l[n-1], "", true
-	}
-	if n >= 1 && KnownArch[l[n-1]] {
-		return "", l[n-1], true
-	}
-	return "", "", false
-}

